tagPath = self.custom.assetInfo.tagPath

if (tagPath or None) is None: return []

tagSearchList = [
					{'tagPath': tagPath, 'filters': {"tagType":"UdtInstance", "typeId": "Kanoa/measure","recursive":True}},
					{'tagPath': tagPath, 'filters': {"tagType":"UdtInstance", "typeId": "[Kanoa]_types_/Kanoa/measure", "recursive":True}}
				]

tagInfoList = []
for ts in tagSearchList:
	results = system.tag.browse(path = ts['tagPath'], filter = ts['filters']).results
	for result in results:
		path = str(result['fullPath'])
		tagName = str(result['name'])

		parentPath = path.rsplit('/', len(tagName.split("/"))-1)[0]
		tagInfoList.append({'tagName': tagName, 'tagPath': path, 'parentPath': parentPath, 'udtType': result['typeId']})

tags = []
if len(tagInfoList) > 0:
	tagValues = system.tag.readBlocking([item['tagPath'] + '/outOfControl' for item in tagInfoList])
	for i, tagValue in enumerate(tagValues):
		if tagValue.value:
			violations = system.tag.readBlocking(item['tagPath'] + '/ruleViolations')
			if len(violations) > 0: violations = violations[0]
			tags.append({'tagName': tagInfoList[i]['tagName'], 'tagPath': tagInfoList[i]['tagPath'], 'violations': violations})

return tags

